def reserve_items(items):
    from contextlib import ExitStack

    ordered_items = sorted(items, key=lambda item: item.id)
    with ExitStack() as stack:
        acquired_ids = set()
        for item in ordered_items:
            if item.id not in acquired_ids:
                stack.enter_context(lock_item(item.id))
                acquired_ids.add(item.id)
        for item in ordered_items:
            decrement_stock(item)
